package com.singtel.ruleengineservice;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;class RuleModelTest{@Test void nestedLogicAndExplanation(){var rule=new RuleModel.Expression(RuleModel.Op.AND,null,null,List.of(new RuleModel.Expression(RuleModel.Op.EQ,"segment","Postpaid",null),new RuleModel.Expression(RuleModel.Op.NOT,null,null,List.of(new RuleModel.Expression(RuleModel.Op.EQ,"excluded","true",null)))));var result=RuleModel.evaluate(rule,Map.of("segment","Postpaid","excluded",false));assertTrue(result.eligible());assertTrue(result.reasons().stream().anyMatch(s->s.startsWith("NOT group")));assertFalse(RuleModel.evaluate(rule,Map.of("segment","Prepaid","excluded",false)).eligible());}@Test void spendBoundaryUsesDecimal(){var rule=new RuleModel.Expression(RuleModel.Op.GTE,"spend","40.01",null);assertTrue(RuleModel.evaluate(rule,Map.of("spend","40.01")).eligible());assertFalse(RuleModel.evaluate(rule,Map.of("spend","40.00")).eligible());}@Test void unsafeFieldAndExcessiveDepthRejected(){assertThrows(IllegalArgumentException.class,()->RuleModel.validate(new RuleModel.Expression(RuleModel.Op.EQ,"sql","DROP TABLE",null)));var e=new RuleModel.Expression(RuleModel.Op.EQ,"segment","Postpaid",null);for(int i=0;i<10;i++)e=new RuleModel.Expression(RuleModel.Op.NOT,null,null,List.of(e));var deep=e;assertThrows(IllegalArgumentException.class,()->RuleModel.validate(deep));}@Test void missingFactsFailClosed(){assertFalse(RuleModel.evaluate(new RuleModel.Expression(RuleModel.Op.EQ,"segment","null",null),Map.of()).eligible());}}